function sum(a, b) {
  console.log(this.n + a + b);
}
sum.call({ n: 1 }, 2, 3);
sum.apply({ n: 1 }, [4, 5]);

function sum(a, b) {
  console.log(this.n + a + b);
}
const sumFrom = sum.bind({ n: 1 }, 2);
sumFrom(3);
sumFrom(4);

function show() {
  console.log(this.n);
}
const show1 = show.bind({ n: 1 });
show1.call({ n: 2 });
show1.apply({ n: 3 });

const box = {
  n: 1,
  show(x) {
    console.log(x + this.n);
  },
};
[2, 3].forEach(box.show, box);

const box = {
  n: 2,
  run() {
    [1, 4].forEach((x) => console.log(x + this.n));
  },
};
box.run();

class Box {
  n = 1;
  method() {
    console.log(this.n);
  }
  field = () => {
    console.log(this.n);
  };
}
const box = new Box();
const method = box.method;
const field = box.field;
try {
  method();
} catch {
  console.log(2);
}
field();

const outer = {
  n: 1,
  make() {
    const inner = {
      n: 2,
      show: () => console.log(this.n),
    };
    inner.show();
    console.log(inner.n);
  },
};
outer.make();

function Box(n) {
  this.n = n;
  return this.n;
}
const Bound = Box.bind({ n: 9 });
console.log(new Bound(1).n);
console.log(Bound(2));
